create type public.conversation_mode as enum ('ai','human');create type public.message_direction as enum ('inbound','outbound');create type public.message_source as enum ('customer','ai','human','system');
create table public.conversations(id uuid primary key default gen_random_uuid(),barbershop_id uuid not null references public.barbershops(id) on delete cascade,customer_id uuid not null references public.customers(id) on delete cascade,mode public.conversation_mode not null default 'ai',assigned_user_id uuid references public.profiles(id) on delete set null,last_message_at timestamptz not null default now(),unread_count integer not null default 0 check(unread_count>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(barbershop_id,customer_id));
create table public.messages(id uuid primary key default gen_random_uuid(),barbershop_id uuid not null references public.barbershops(id) on delete cascade,conversation_id uuid not null references public.conversations(id) on delete cascade,direction public.message_direction not null,source public.message_source not null,body text not null,external_message_id text,status text,created_at timestamptz not null default now());
create table public.ai_settings(id uuid primary key default gen_random_uuid(),barbershop_id uuid not null unique references public.barbershops(id) on delete cascade,enabled boolean not null default true,assistant_name text not null default 'Assistente TENVYQA',tone text not null default 'friendly' check(tone in('professional','friendly','casual')),welcome_message text,business_description text,address text,payment_methods text,parking_info text,cancellation_policy text,late_policy text,updated_at timestamptz not null default now());
create table public.knowledge_base(id uuid primary key default gen_random_uuid(),barbershop_id uuid not null references public.barbershops(id) on delete cascade,title text not null,content text not null,category text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index on public.conversations(barbershop_id,last_message_at desc);create index on public.messages(conversation_id,created_at);create index on public.knowledge_base(barbershop_id,active);
alter table public.conversations enable row level security;alter table public.messages enable row level security;alter table public.ai_settings enable row level security;alter table public.knowledge_base enable row level security;
create policy "members manage conversations" on public.conversations for all using(public.is_barbershop_member(barbershop_id)) with check(public.is_barbershop_member(barbershop_id));
create policy "members manage messages" on public.messages for all using(public.is_barbershop_member(barbershop_id)) with check(public.is_barbershop_member(barbershop_id));
create policy "members read ai settings" on public.ai_settings for select using(public.is_barbershop_member(barbershop_id));create policy "admins manage ai settings" on public.ai_settings for all using(public.has_barbershop_role(barbershop_id,array['owner','manager']::public.member_role[])) with check(public.has_barbershop_role(barbershop_id,array['owner','manager']::public.member_role[]));
create policy "members read knowledge" on public.knowledge_base for select using(public.is_barbershop_member(barbershop_id));create policy "admins manage knowledge" on public.knowledge_base for all using(public.has_barbershop_role(barbershop_id,array['owner','manager']::public.member_role[])) with check(public.has_barbershop_role(barbershop_id,array['owner','manager']::public.member_role[]));
create or replace function public.set_conversation_mode(p_conversation uuid,p_mode public.conversation_mode) returns void language plpgsql security definer set search_path=public as $$declare v_shop uuid;begin select barbershop_id into v_shop from public.conversations where id=p_conversation;if not public.has_barbershop_role(v_shop,array['owner','manager','receptionist']::public.member_role[]) then raise exception 'Not authorized';end if;update public.conversations set mode=p_mode,assigned_user_id=case when p_mode='human' then auth.uid() else null end,updated_at=now() where id=p_conversation;end$$;grant execute on function public.set_conversation_mode(uuid,public.conversation_mode) to authenticated;